package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.TokenId;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ResolvableDeserializer;
import com.fasterxml.jackson.databind.deser.std.JsonDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.Capability;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class UntypedObjectDeserializer_deserialize_TriageGen0Test {

    private UntypedObjectDeserializer deserializer;
    private JsonParser p;
    private DeserializationContext ctxt;

    // Mocking internal fields via a subclass or reflection is hard because they are private.
    // However, we can use the constructor or spy to inject behavior if needed.
    // Since the fields like _mapDeserializer are private, we will use a spy and 
    // rely on the provided public/protected methods or mock the dependencies.

    @Before
    public void setUp() {
        deserializer = new UntypedObjectDeserializer();
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
    }

    @Test
    public void testDeserialize_StartObject_NoMapDeserializer() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.START_OBJECT);
        UntypedObjectDeserializer spyDeserializer = spy(deserializer);
        doReturn(null).when(spyDeserializer).mapObject(any(), any());
        doReturn("mapResult").when(spyDeserializer).mapObject(p, ctxt);

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals("mapResult", result);
    }

    @Test
    public void testDeserialize_FieldName_NoMapDeserializer() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.FIELD_NAME);
        UntypedObjectDeserializer spyDeserializer = spy(deserializer);
        doReturn("mapResult").when(spyDeserializer).mapObject(p, ctxt);

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals("mapResult", result);
    }

    @Test
    public void testDeserialize_StartArray_UseJavaArray() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.START_ARRAY);
        when(ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)).thenReturn(true);
        UntypedObjectDeserializer spyDeserializer = spy(deserializer);
        doReturn(new Object[]{"arr"}).when(spyDeserializer).mapArrayToArray(p, ctxt);

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals(new Object[]{"arr"}, result);
    }

    @Test
    public void testDeserialize_StartArray_NoJavaArray_NoListDeserializer() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.START_ARRAY);
        when(ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)).thenReturn(false);
        UntypedObjectDeserializer spyDeserializer = spy(deserializer);
        doReturn("listResult").when(spyDeserializer).mapArray(p, ctxt);

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals("listResult", result);
    }

    @Test
    public void testDeserialize_EmbeddedObject() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.valueOf("ID_EMBEDDED_OBJECT")); 
        // Note: JsonTokenId is internal/custom in some Jackson versions, 
        // but the code uses JsonTokenId.ID_EMBEDDED_OBJECT. 
        // If JsonToken doesn't have it, we mock the return of getCurrentTokenId.
        // Assuming ID_EMBEDDED_OBJECT maps to a specific integer or token.
        // Since we can't easily mock the enum if it's not standard, we assume the switch hits.

        // For the sake of this test, we simulate the ID_EMBEDDED_OBJECT token via a mock if possible.
        // Since JsonToken is an enum, we can't mock it, but we can mock the behavior of the switch.
        // Let's assume the token is provided.
    }

    @Test
    public void testDeserialize_String_NoStringDeserializer() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_STRING);
        when(p.getText()).thenReturn("hello");

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals("hello", result);
    }

    @Test
    public void testDeserialize_NumberInt_NoNumberDeserializer_NoCoercion() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        when(p.getNumberValue()).thenReturn(123);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(123, result);
    }

    @Test
    public void testDeserialize_NumberFloat_UseBigDecimal() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_NUMBER_FLOAT);
        when(ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)).thenReturn(true);
        BigDecimal bd = new BigDecimal("1.23");
        when(p.getDecimalValue()).thenReturn(bd);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(bd, result);
    }

    @Test
    public void testDeserialize_NumberFloat_UseDouble() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_NUMBER_FLOAT);
        when(ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)).thenReturn(false);
        when(p.getDoubleValue()).thenReturn(1.23);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(1.23, (Double)result, 0.001);
    }

    @Test
    public void testDeserialize_True() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.TRUE);
        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(Boolean.TRUE, result);
    }

    @Test
    public void testDeserialize_False() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.FALSE);
        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(Boolean.FALSE, result);
    }

    @Test
    public void testDeserialize_Null() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_NULL);
        Object result = deserializer.deserialize(p, ctxt);
        assertNull(result);
    }

    @Test(expected = JsonMappingException.class)
    public void testDeserialize_Default_ThrowsException() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.START_ARRAY); 
        // We need to force the switch to default. 
        // Since START_ARRAY is handled, we pick a token not in the switch.
        // Note: In a real scenario, we'd use a token ID that doesn't match any case.
        when(p.getCurrentTokenId()).thenReturn(JsonToken.END_ARRAY); 
        when(ctxt.mappingException(Object.class)).thenThrow(new JsonMappingException(null, "error"));

        deserializer.deserialize(p, ctxt);
    }

    // Note: Testing the "if (_mapDeserializer != null)" branches requires 
    // injecting the private field via reflection because the constructor doesn't expose it.
    @Test
    public void testDeserialize_StartObject_WithMapDeserializer() throws Exception {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.START_OBJECT);
        JsonDeserializer<Object> mockMapDeser = mock(JsonDeserializer.class);
        when(mockMapDeser.deserialize(p, ctxt)).thenReturn("mapped_object");

        // Use reflection to set the private field _mapDeserializer
        java.lang.reflect.Field field = UntypedObjectDeserializer.class.getDeclaredField("_mapDeserializer");
        field.setAccessible(true);
        field.set(deserializer, mockMapDeser);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals("mapped_object", result);
    }

    @Test
    public void testDeserialize_String_WithStringDeserializer() throws Exception {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_STRING);
        JsonDeserializer<Object> mockStringDeser = mock(JsonDeserializer.class);
        when(mockStringDeser.deserialize(p, ctxt)).thenReturn("custom_string");

        java.lang.reflect.Field field = UntypedObjectDeserializer.class.getDeclaredField("_stringDeserializer");
        field.setAccessible(true);
        field.set(deserializer, mockStringDeser);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals("custom_string", result);
    }

    @Test
    public void testDeserialize_NumberInt_WithNumberDeserializer() throws Exception {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        JsonDeserializer<Object> mockNumberDeser = mock(JsonDeserializer.class);
        when(mockNumberDeser.deserialize(p, ctxt)).thenReturn(999);

        java.lang.reflect.Field field = UntypedObjectDeserializer.class.getDeclaredField("_numberDeserializer");
        field.setAccessible(true);
        field.set(deserializer, mockNumberDeser);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(999, result);
    }

    @Test
    public void testDeserialize_StartArray_WithListDeserializer() throws Exception {
        when(p.getCurrentTokenId()).thenReturn(JsonToken.START_ARRAY);
        when(ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)).thenReturn(false);
        JsonDeserializer<Object> mockListDeser = mock(JsonDeserializer.class);
        when(mockListDeser.deserialize(p, ctxt)).thenReturn("custom_list");

        java.lang.reflect.Field field = UntypedObjectDeserializer.class.getDeclaredField("_listDeserializer");
        field.setAccessible(true);
        field.set(deserializer, mockListDeser);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals("custom_list", result);
    }
}
